export const RULE_REGISTRY=Object.freeze({
  rule_board:{id:'rule_board',source:'docs/releases/RULE-COVERAGE.md',verification:'tested_implementation',conditions:'Thời Gia Chuyển Bàn, cùng pháp và giờ dân dụng; dữ kiện từ core, không phải bằng chứng dự báo.'},
  rule_actor:{id:'rule_actor',source:'dist/qimen/analysis/usefulGod.mjs',verification:'app_convention_unverified',conditions:'Nhật can chỉ đại diện người hỏi việc của mình; hỏi thay dùng Can Chi được người dùng xác nhận. Thời can là bối cảnh sự việc, không tự là khách hàng.'},
  rule_yongshen_v2:{id:'rule_yongshen_v2',source:'docs/releases/KM-YONGSHEN-2.0.md',verification:'multi_source_domain_convention',conditions:'KM-YONGSHEN-2.0 chọn Dụng Thần theo domain và xếp primary/secondary/counterpart/corroborator/operational. Các ánh xạ là quy ước luận có nguồn đối chiếu; không xác minh danh tính, động cơ, chẩn đoán hoặc kết quả ngoài thực tế.'},
  rule_structure_v2:{id:'rule_structure_v2',source:'docs/releases/KM-STRUCTURE-2.0.md',verification:'source_bounded_corpus',conditions:'KM-STRUCTURE-2.0 bao phủ 81 Thập Can Khắc Ứng, Tứ hại và một tập cách cục ưu tiên. Chỉ cấu trúc gắn đúng vai/Dụng Thần mới được nâng trọng số; tone là mức ưu tiên nội bộ, không phải xác suất hay phán quyết.'},
  rule_keying_v3:{id:'rule_keying_v3',source:'docs/releases/KM-KEYING-3.0.md',verification:'source_bounded_role_attached',conditions:'KM-KEYING-3.0 thêm Bát Môn Khắc Ứng, Tam Kỳ đáo cung, Hòa/Nghĩa/Bức/Chế và chỉ mục Cửu Tinh trị thời. Đây là lớp điều kiện gắn đúng cung/vai, không phải phiếu độc lập hay xác suất. Cửu Tinh trị thời hiện chỉ classical_context_only, không tự biến ứng tượng cổ thành dự báo hiện đại.'},
  rule_formation_v3:{id:'rule_formation_v3',source:'docs/releases/KM-FORMATION-3.0.md',verification:'source_profiled_strategic_layer',conditions:'KM-FORMATION-3.0 dùng profile 奇門法竅 cho Tam Trá, Ngũ Giả, Cửu Độn và tính Thiên Tam Môn/Địa Tứ Hộ theo tiết khí–chi giờ. Cách cục chỉ mô tả kiểu hành động/phương vị truyền thống; không tham gia evidenceScore, không đổi primaryJudgment/thứ hạng so sánh, không bảo đảm an toàn hoặc thành công.'},
  rule_role_v2:{id:'rule_role_v2',source:'docs/releases/KM-ROLE-2.0.md',verification:'contextual_host_guest_with_app_agency',conditions:'KM-ROLE-2.0 coi Chủ–Khách là tư thế theo sự việc, không phải danh tính cố định; Nội/Ngoại chỉ là xu hướng gần–xa/nhanh–chậm; agency và chiều tác động là lớp tổng hợp biểu tượng, không xác minh quyền lực, ý chí hoặc bên thắng/thua ngoài thực tế.'},
  rule_timeplace_v2:{id:'rule_timeplace_v2',source:'docs/releases/KM-TIMEPLACE-2.0.md',verification:'iana_civil_opt_in_solar_metadata_only',conditions:'KM-TIMEPLACE-2.0 mặc định giữ fixed UTC offset. IANA civil mode là opt-in và resolve offset lịch sử/DST; giờ DST bị lặp cần disambiguation, giờ không tồn tại bị chặn. Tọa độ/giờ Mặt Trời chỉ là metadata và không tự đổi giờ lập bàn.'},
  rule_proxy:{id:'rule_proxy',source:'dist/qimen/modes/semantics.mjs',verification:'app_convention_unverified',conditions:'Ánh xạ vai hiện đại là quy ước của ứng dụng, chưa xác minh nguồn truyền thống cho từng trường hợp; không chứng minh danh tính, doanh thu hay lợi nhuận.'},
  rule_user_mapping:{id:'rule_user_mapping',source:'user_input',verification:'user_confirmed_mapping',conditions:'Người dùng xác nhận Can Chi đại diện; code định vị can, không xác thực căn cứ chọn Can Chi của người dùng.'},
  rule_elements:{id:'rule_elements',source:'docs/releases/RULE-COVERAGE.md',verification:'declared_convention',conditions:'Sinh/khắc xét hành cung theo đúng chiều, không phải quan hệ nhân quả hay xác suất.'},
  rule_conditions:{id:'rule_conditions',source:'docs/releases/RULE-COVERAGE.md',verification:'tested_declared_scope',conditions:'Không/Mã theo chi giờ; lưu riêng chiều Môn khắc Cung và Cung khắc Môn; hình/mộ xét từng can kể cả can ký; mộ hiện chỉ bao gồm Tam kỳ.'},
  rule_strength:{id:'rule_strength',source:'docs/releases/KM-STRENGTH-2.0.md',verification:'source_separated_models',conditions:'KM-STRENGTH-2.0 tách Cửu Tinh, Bát Môn, Thập Can–Thập Nhị Trường Sinh và môi trường Cung thành các mô hình riêng. Trọng số chỉ xếp ưu tiên nội bộ, không phải xác suất; không dùng một công thức thay cho lớp khác.'},
  rule_synthesis:{id:'rule_synthesis',source:'dist/qimen/ai/reasoningPlanner.mjs',verification:'app_convention_unverified',conditions:'Tổng hợp tượng thành giả thuyết có điều kiện; điểm ưu tiên chỉ là tiêu chí nội bộ, không phải công thức cổ truyền hoặc xác suất.'},
  rule_stages:{id:'rule_stages',source:'dist/qimen/ai/outcomeDimensions.mjs',verification:'app_convention_unverified',conditions:'Bảy tầng phân biệt hỗ trợ biểu tượng với sự kiện đã xảy ra. Môn thuận cần phối hợp vai sự việc và cụm Tinh/Thần/Can; Không giới hạn đúng tầng, không phủ định tự động cơ hội.'},
  rule_timing_scope:{id:'rule_timing_scope',source:'dist/qimen/ai/timingEngine.mjs',verification:'tested_response_window_scan_v2',conditions:'KM-YINGQI-2.0 chỉ quét ứng kỳ khi người dùng đã nêu phạm vi thời gian. Nhịp nhanh/chậm dùng Nội/Ngoại bàn và Phản/Phục ngâm như tín hiệu riêng; không tự tạo ngày. Trigger định ngày ưu tiên Không vong: điền/xung Không → Mã tinh: lâm/xung Mã → Tam kỳ nhập mộ: đến Mộ/xung Mộ. Mốc chỉ là cửa sổ kích hoạt để kiểm chứng; Hình, Phản/Phục ngâm, Can/Môn và nhập mộ ngoài Tam kỳ chưa tự định ngày.'},
});
export function selectionProvenance(role) {
  const id=role.status==='user_supplied'?'rule_user_mapping':['self','event'].includes(role.id)?'rule_actor':role.resolverVersion==='KM-YONGSHEN-2.0'?'rule_yongshen_v2':'rule_proxy';
  return {selectionRule:RULE_REGISTRY[id],limitations:[RULE_REGISTRY[id].conditions,...(role.status==='unresolved'?['Chưa xác định đại diện; không gán cung của một biểu tượng cho người này.']:[])]};
}
